var out = '';
if(m){
  var dec = '';
  try { dec = java.base64Decode(decodeURIComponent(m[1])); } catch(e) {}
  if(/^https?:\/\//.test(dec)){ out = dec; }
  else { out = "https://www.rrssk.com/?action=go&t=" + m[1]; }
} else {
  var m2 = result.match(/window\.open\('([^']+)'/);
  if(m2){
    var rel = m2[1].replace(/&amp;/g, "&");
    out = (/^https?:/i.test(rel)) ? rel : "https://www.rrssk.com/" + rel.replace(/^\//, "");
  }
}
result = out;

